import React, { useState, useRef } from "react";
import axios from "axios";
import "./SubmitProposal.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";
import "./BackupRestore.css";

const BackupRestore = () => {
  const [restoreStatus, setRestoreStatus] = useState('');
  const [resetStatus, setResetStatus] = useState('');
  const [downloadStatus, setDownloadStatus] = useState('');
  const fileInput = useRef(null);

  const downloadBackup = async () => {
    try {
      setDownloadStatus("Preparing backup...");
      const res = await axios.get('http://localhost:5000/admin/backup', {
        responseType: 'blob',
      });

      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', 'backup.zip');
      document.body.appendChild(link);
      link.click();
      link.remove();

      setDownloadStatus("Download complete!");
    } catch (err) {
      console.error(err);
      setDownloadStatus("Download failed.");
    }
  };

  const uploadRestore = async () => {
    const file = fileInput.current.files[0];
    if (!file) {
      setRestoreStatus("No file selected.");
      return;
    }

    setRestoreStatus(`Restoring from ${file.name}...`);

    const formData = new FormData();
    formData.append('backup', file);

    try {
      const res = await axios.post('http://localhost:5000/admin/restore', formData);
      if (res.status === 200) {
        setRestoreStatus('Restore completed successfully!');
      } else {
        setRestoreStatus('Restore failed. Try again.');
      }
    } catch (error) {
      console.error(error);
      setRestoreStatus('An error occurred during restore.');
    }
  };

  const handleReset = async () => {
    if (window.confirm('Are you sure you want to reset the system? This will remove all data.')) {
      setResetStatus('System reset in progress...');
      try {
        const response = await axios.post('http://localhost:5000/api/admin/clear-all');
        if (response.status === 200) {
          setResetStatus('System reset completed successfully!');
        } else {
          setResetStatus('Failed to reset the system.');
        }
      } catch (error) {
        console.error("System reset error:", error);
        setResetStatus('An error occurred while resetting.');
      }
    }
  };

  return (
    <div className="proposal-container">
      <Navbar /><br /><br /><br />
      <div className="content-wrapper">
        <AdminSidebar />

        <div className="backup-page">
          <div className="heading">
            <h1>Backup and Restore System</h1>
            <p>Manage system backups, restore from files, or reset the database.</p>
          </div>

          <div className="container">
            <div className="card">
              <h3>System Restore</h3>
              <p>Restore data from a backup file</p>
              <input type="file" ref={fileInput} />
              <button onClick={uploadRestore}>Restore</button>
              {restoreStatus && <p>{restoreStatus}</p>}
            </div>

            <div className="card">
              <h3>System Reset</h3>
              <p>Remove all data from the database</p>
              <button onClick={handleReset}>Reset System</button>
              {resetStatus && <p>{resetStatus}</p>}
            </div>

            <div className="card">
              <h3>Download Backup</h3>
              <p>Download the latest backup file</p>
              <button onClick={downloadBackup}>Download Backup</button>
              {downloadStatus && <p>{downloadStatus}</p>}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default BackupRestore;
